CREATE FUNCTION public.quote_has_contract(_quote uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT signed_at IS NOT NULL OR pm_project_id IS NOT NULL OR EXISTS(SELECT 1 FROM quote_contract_references r WHERE r.quote_id=q.id) FROM fee_proposals q WHERE q.id=_quote),true) $$;
REVOKE ALL ON FUNCTION public.quote_has_contract(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.pm_has_gantt_contract(_project uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p pm_projects; q fee_proposals; BEGIN SELECT * INTO p FROM pm_projects WHERE id=_project; IF p.id IS NULL THEN RETURN true; END IF; IF EXISTS(SELECT 1 FROM pm_project_contract_baseline WHERE project_id=_project) OR EXISTS(SELECT 1 FROM pm_project_commercial_baselines WHERE project_id=_project) OR EXISTS(SELECT 1 FROM contracts WHERE source_project_id=_project AND signed_at IS NOT NULL) OR EXISTS(SELECT 1 FROM fee_proposals WHERE pm_project_id=_project) THEN RETURN true; END IF; SELECT * INTO q FROM fee_proposals WHERE id=p.quote_id; IF q.id IS NULL THEN RETURN true; END IF; RETURN public.quote_has_contract(q.id); END $$;
REVOKE ALL ON FUNCTION public.pm_has_gantt_contract(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.quote_capture_contract_reference() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rows jsonb; BEGIN IF (NEW.signed_at IS NOT NULL OR NEW.pm_project_id IS NOT NULL) AND OLD.signed_at IS NULL AND OLD.pm_project_id IS NULL THEN SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'parentId',s.parent_stage_id,'kind',s.stage_kind,'budget',s.budget,'fee',public.pm_quote_stage_billing_fee(s.id),'monthly',s.retainer_monthly_amount,'months',s.retainer_months) ORDER BY s.sort_order,s.id),'[]') INTO rows FROM quote_stages s WHERE s.quote_id=NEW.id; INSERT INTO quote_contract_references(quote_id,boundary,stages,total,evidence_snapshot_id) VALUES(NEW.id,CASE WHEN NEW.signed_at IS NOT NULL THEN 'signature' ELSE 'conversion' END,rows,(public.pm_quote_conversion_totals(NEW.id)->>'total_fee')::numeric,NEW.accepted_snapshot_id) ON CONFLICT(quote_id) DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.quote_capture_contract_reference() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER quote_capture_contract_reference AFTER UPDATE OF signed_at,pm_project_id ON public.fee_proposals FOR EACH ROW EXECUTE FUNCTION public.quote_capture_contract_reference();
CREATE FUNCTION public.quote_commercial_state(_quote uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE q fee_proposals; r quote_contract_references; BEGIN IF auth.uid() IS NULL OR NOT public.is_psa_staff() OR NOT(public.has_role(auth.uid(),'admin') OR public.has_permission(auth.uid(),'crm.pipeline')) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; SELECT * INTO q FROM fee_proposals WHERE id=_quote; IF q.id IS NULL THEN RAISE EXCEPTION 'Quote not found'; END IF; SELECT * INTO r FROM quote_contract_references WHERE quote_id=_quote; RETURN jsonb_build_object('hasContract',public.quote_has_contract(_quote),'stages',coalesce(r.stages,'[]'),'contractedTotal',r.total,'referencePending',r.quote_id IS NULL); END $$;
REVOKE ALL ON FUNCTION public.quote_commercial_state(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.quote_commercial_state(uuid) TO authenticated,service_role;
CREATE FUNCTION public.quote_gantt_change_value(_stage uuid,_expected numeric,_value numeric,_reason text DEFAULT '',_responsibility boolean DEFAULT false,_client_agreed boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s quote_stages; q fee_proposals; contracted boolean; previous text; BEGIN IF auth.uid() IS NULL OR NOT public.is_psa_staff() OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; SELECT f.* INTO q FROM fee_proposals f WHERE f.id=(SELECT quote_id FROM quote_stages WHERE id=_stage) FOR UPDATE; SELECT * INTO s FROM quote_stages WHERE id=_stage FOR UPDATE; IF s.id IS NULL OR q.id IS NULL OR q.is_locked OR q.locked_at IS NOT NULL OR q.pm_project_id IS NOT NULL OR q.locked_project_id IS NOT NULL THEN RAISE EXCEPTION 'gantt.schedule.locked'; END IF; contracted:=public.quote_has_contract(q.id); IF contracted AND (_responsibility IS DISTINCT FROM true OR length(trim(coalesce(_reason,''))) NOT BETWEEN 3 AND 240 OR (s.stage_kind='retainer_monthly' AND _client_agreed IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'Responsibility confirmation and a short reason are required'; END IF; IF _value IS NULL OR _value<0 OR _value::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Stage value must be non-negative'; END IF; IF (CASE WHEN s.stage_kind='retainer_monthly' THEN s.retainer_monthly_amount ELSE s.budget END) IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'Value changed elsewhere; reload before confirming' USING ERRCODE='40001'; END IF; previous:=coalesce(current_setting('quote.retainer_value_action',true),''); PERFORM set_config('quote.retainer_value_action','yes',true); IF s.stage_kind='retainer_monthly' THEN UPDATE quote_stages SET retainer_monthly_amount=_value,manual_override=true WHERE id=_stage; IF contracted THEN INSERT INTO quote_retainer_value_history(quote_id,stage_id,actor,old_value,new_value,reason) VALUES(q.id,s.id,auth.uid(),_expected,_value,trim(_reason)); END IF; ELSE UPDATE quote_stages SET budget=_value,manual_override=true WHERE id=_stage; IF contracted THEN INSERT INTO quote_gantt_value_history(quote_id,stage_id,actor,old_value,new_value,reason) VALUES(q.id,s.id,auth.uid(),_expected,_value,trim(_reason)); END IF; END IF; PERFORM set_config('quote.retainer_value_action',previous,true); END $$;
REVOKE ALL ON FUNCTION public.quote_gantt_change_value(uuid,numeric,numeric,text,boolean,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.quote_gantt_change_value(uuid,numeric,numeric,text,boolean,boolean) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.quote_retainer_change_value(_stage uuid,_expected numeric,_value numeric,_reason text,_responsibility boolean,_client_agreed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM quote_stages WHERE id=_stage AND stage_kind='retainer_monthly') THEN RAISE EXCEPTION 'gantt.schedule.locked'; END IF; PERFORM public.quote_gantt_change_value(_stage,_expected,_value,_reason,_responsibility,_client_agreed); END $$;
CREATE OR REPLACE FUNCTION public.quote_retainer_value_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.quote_id IS DISTINCT FROM OLD.quote_id THEN RAISE EXCEPTION 'Stage quote origin is immutable'; END IF; PERFORM 1 FROM fee_proposals WHERE id=NEW.quote_id FOR UPDATE; IF (NEW.retainer_monthly_amount,NEW.budget) IS DISTINCT FROM (OLD.retainer_monthly_amount,OLD.budget) AND public.quote_has_contract(NEW.quote_id) AND coalesce(current_setting('quote.retainer_value_action',true),'')<>'yes' THEN RAISE EXCEPTION 'Confirm responsibility and give a reason before changing a value' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER quote_gantt_budget_contract_guard BEFORE UPDATE OF budget,quote_id ON public.quote_stages FOR EACH ROW EXECUTE FUNCTION public.quote_retainer_value_guard();
DO $patch$ DECLARE body text; old text; newer text; fn text; BEGIN FOREACH fn IN ARRAY ARRAY['quote_calculator_preview(uuid,jsonb)','quote_apply_calculator(uuid,jsonb,text,text,boolean,boolean)'] LOOP SELECT pg_get_functiondef(('public.'||fn)::regprocedure) INTO body; old:='q.quote_status<>''draft'''; newer:='q.quote_status NOT IN (''draft'',''sent'',''approved'') OR public.quote_has_contract(q.id)'; IF strpos(body,old)=0 THEN RAISE EXCEPTION 'Calculator boundary anchor missing'; END IF; body:=replace(body,old,newer); body:=replace(body,'''manual'',manual,','''manual'',CASE WHEN public.quote_has_contract(q.id) THEN manual ELSE ''[]''::jsonb END,''hasContract'',public.quote_has_contract(q.id),'); body:=replace(body,'IF jsonb_array_length(preview->''manual'')>0 AND NOT _overwrite_manual','IF public.quote_has_contract(q.id) AND jsonb_array_length(preview->''manual'')>0 AND NOT _overwrite_manual'); EXECUTE body; END LOOP; END $patch$;
DO $patch$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.pm_gantt_record_value(public.pm_stages,numeric,numeric,text,text,date)'::regprocedure) INTO body; IF strpos(body,'BEGIN')=0 THEN RAISE EXCEPTION 'History boundary anchor missing'; END IF; body:=replace(body,E'BEGIN\n',E'BEGIN\n IF NOT public.pm_has_gantt_contract(_stage.project_id) THEN RETURN; END IF;\n'); EXECUTE body; SELECT pg_get_functiondef('public.pm_gantt_value_guard()'::regprocedure) INTO body; body:=replace(body,'AND coalesce(current_setting(''pm.gantt_value_action'',true),'''')<>''yes''','AND public.pm_has_gantt_contract(NEW.project_id) AND coalesce(current_setting(''pm.gantt_value_action'',true),'''')<>''yes'''); body:=replace(body,'NEW.outside_contract:=NEW.source_quote_stage_id','NEW.outside_contract:=public.pm_has_gantt_contract(NEW.project_id) AND NEW.source_quote_stage_id'); EXECUTE body; SELECT pg_get_functiondef('public.pm_gantt_change_value(uuid,numeric,numeric,text,boolean,boolean,date)'::regprocedure) INTO body; body:=replace(body,'IF _responsibility IS DISTINCT FROM true OR length(trim(coalesce(_reason,''''))) NOT BETWEEN 3 AND 240','IF public.pm_has_gantt_contract(s.project_id) AND (_responsibility IS DISTINCT FROM true OR length(trim(coalesce(_reason,''''))) NOT BETWEEN 3 AND 240)'); body:=replace(body,E'IF s.stage_kind=''retainer_monthly'' THEN\n',E'IF s.stage_kind=''retainer_monthly'' AND NOT public.pm_has_gantt_contract(s.project_id) THEN\n UPDATE pm_stages SET retainer_monthly_amount=_value WHERE id=s.id;\n RETURN jsonb_build_object(''value'',_value);\n END IF;\n IF s.stage_kind=''retainer_monthly'' THEN\n'); EXECUTE body; SELECT pg_get_functiondef('public.pm_gantt_commercial_read(uuid)'::regprocedure) INTO body; body:=replace(body,'''contractedTotal'',total','''contractedTotal'',total,''hasContract'',public.pm_has_gantt_contract(_project)'); EXECUTE body; END $patch$;